1	import type { Metadata } from "next";
2	import { notFound } from "next/navigation";
3	import { db } from "@/lib/db";
4	import { UseCaseLanding } from "@/components/marketing/UseCaseLanding";
5	import { APP_URL } from "@/components/marketing/StructuredData";
6	import {
7	  findCombo,
8	  buildLanding,
9	  findRegionCombo,
10	  buildRegionLanding,
11	  LANDING_SLUGS,
12	  REGION_LANDING_SLUGS,
13	  type LandingPlan,
14	} from "@/lib/marketing/locationLandings";
15	
16	/**
17	 * Programmatic "(location) (service)" marketing landing pages, plus the
18	 * region-tier umbrella pages above them.
19	 *
20	 * One data-driven route renders the whole location × service matrix defined in
21	 * `lib/marketing/locationLandings.ts` — e.g. /london-vps-hosting,
22	 * /toronto-web-hosting, /frankfurt-game-server-hosting — AND the broader
23	 * region × service matrix above it — e.g. /usa-vps-hosting,
24	 * /europe-game-server-hosting — since both are built by the same data table
25	 * into the same `BuiltLanding` shape and render through the same
26	 * `UseCaseLanding` component. A slug is checked against the region matrix
27	 * first, then the city matrix; anything in neither falls through to a 404,
28	 * so this catch-all never shadows the hand-written marketing pages (which
29	 * win at request time anyway) or invents doorway pages. Real DB plans feed
30	 * the pricing grid and Product rich-result for both tiers.
31	 */
32	
33	export const dynamic = "force-dynamic";
34	
35	// Pre-declare the known slugs so Next can enumerate both matrices; unknown
36	// slugs are rejected in the page/metadata via notFound().
37	export function generateStaticParams(): Array<{ slug: string }> {
38	  return [...REGION_LANDING_SLUGS, ...LANDING_SLUGS].map((slug) => ({ slug }));
39	}
40	
41	async function loadPlans(): Promise<LandingPlan[]> {
42	  return db.plan.findMany({
43	    where: { active: true },
44	    orderBy: { sortOrder: "asc" },
45	  });
46	}
47	
48	function resolveSlug(slug: string, plans: LandingPlan[]) {
49	  const regionCombo = findRegionCombo(slug);
50	  if (regionCombo) return buildRegionLanding(regionCombo, plans);
51	  const combo = findCombo(slug);
52	  if (combo) return buildLanding(combo, plans);
53	  return undefined;
54	}
55	
56	export async function generateMetadata({
57	  params,
58	}: {
59	  params: Promise<{ slug: string }>;
60	}): Promise<Metadata> {
61	  const { slug } = await params;
62	  const plans = await loadPlans();
63	  const built = resolveSlug(slug, plans);
64	  if (!built) return {};
65	
66	  const url = `${APP_URL}/${slug}`;
67	
68	  return {
69	    title: built.metaTitle,
70	    description: built.metaDescription,
71	    alternates: { canonical: `/${slug}` },
72	    openGraph: {
73	      type: "article",
74	      title: built.ogTitle,
75	      description: built.ogDescription,
76	      url,
77	    },
78	    twitter: {
79	      card: "summary_large_image",
80	      title: built.ogTitle,
81	      description: built.ogDescription,
82	    },
83	  };
84	}
85	
86	export default async function LocationServiceLandingPage({
87	  params,
88	}: {
89	  params: Promise<{ slug: string }>;
90	}) {
91	  const { slug } = await params;
92	  const plans = await loadPlans();
93	  const built = resolveSlug(slug, plans);
94	  if (!built) notFound();
95	
96	  const url = `${APP_URL}/${slug}`;
97	
98	  // BreadcrumbList — helps Google render the Home › <Page> trail and reinforces
99	  // the page's place in the site. FAQ + Product JSON-LD are emitted by
100	  // UseCaseLanding from the same content, so all three rich results are covered.
101	  const breadcrumb = {
102	    "@context": "https://schema.org",
103	    "@type": "BreadcrumbList",
104	    itemListElement: [
105	      { "@type": "ListItem", position: 1, name: "Home", item: APP_URL },
106	      { "@type": "ListItem", position: 2, name: built.breadcrumbName, item: url },
107	    ],
108	  };
109	
110	  return (
111	    <>
112	      <script
113	        type="application/ld+json"
114	        dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumb) }}
115	      />
116	      <UseCaseLanding content={built.content} plans={plans} />
117	    </>
118	  );
119	}
