1	import Link from "next/link";
2	import { Reveal } from "./Reveal";
3	import { Section, SectionTitle, PageHero } from "./primitives";
4	import { CtaBand } from "./sections";
5	import { PricingGrid, type PlanCard } from "./PricingGrid";
6	import { FaqJsonLd, ProductJsonLd } from "./StructuredData";
7	
8	/**
9	 * Shared shell for high-intent "host X on a VPS" use-case landing pages.
10	 *
11	 * The layout is consistent (premium, converts); the SUBSTANCE — intro prose,
12	 * why-points, deploy steps, FAQ — comes entirely from per-page `content`, so
13	 * every page is genuinely unique (not a thin/doorway template). Real plans feed
14	 * the pricing grid and the Product rich-result. Each page is a server component
15	 * that fetches `db.plan` and passes it here.
16	 */
17	export type UseCaseContent = {
18	  eyebrow: string;
19	  /** H1 lead-in (rendered plain) + the gradient highlight word/phrase. */
20	  title: string;
21	  highlight: string;
22	  sub: string;
23	  /** 1–3 short paragraphs of unique, specific prose. */
24	  intro: string[];
25	  /** Section title for the value props, e.g. "Built for Minecraft servers". */
26	  whyTitle: string;
27	  why: { title: string; body: string }[];
28	  /** 3–5 concrete steps to deploy X on the server. */
29	  steps: { title: string; body: string }[];
30	  /** Optional sizing hint shown above the plans. */
31	  specNote?: string;
32	  faq: { q: string; a: string }[];
33	  /** Internal links to related pages (crawl + authority flow). */
34	  related?: { label: string; href: string }[];
35	};
36	
37	export function UseCaseLanding({
38	  content,
39	  plans,
40	}: {
41	  content: UseCaseContent;
42	  plans: PlanCard[];
43	}) {
44	  return (
45	    <>
46	      <FaqJsonLd items={content.faq} />
47	      {plans.length > 0 && <ProductJsonLd plans={plans} />}
48	
49	      <PageHero
50	        eyebrow={content.eyebrow}
51	        title={content.title}
52	        highlight={content.highlight}
53	        sub={content.sub}
54	        primary={{ label: "Deploy now", href: "/register" }}
55	        secondary={{ label: "See pricing", href: "#pricing" }}
56	      />
57	
58	      {/* Intro prose */}
59	      <Section tone="base" size="md">
60	        <div className="mx-auto max-w-3xl space-y-4 text-[15px] leading-relaxed text-slate-300">
61	          {content.intro.map((p, i) => (
62	            <Reveal as="p" key={i} delay={i * 60}>
63	              {p}
64	            </Reveal>
65	          ))}
66	        </div>
67	      </Section>
68	
69	      {/* Why Nxeon for X */}
70	      <Section tone="panel" size="md">
71	        <SectionTitle eyebrow="Why Nxeon" title={content.whyTitle} />
72	        <div className="mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
73	          {content.why.map((w, i) => (
74	            <Reveal key={w.title} delay={i * 60} className="card">
75	              <h3 className="text-base font-semibold text-white">{w.title}</h3>
76	              <p className="mt-2 text-sm leading-relaxed text-slate-400">{w.body}</p>
77	            </Reveal>
78	          ))}
79	        </div>
80	      </Section>
81	
82	      {/* Deploy steps */}
83	      <Section tone="base" size="md">
84	        <SectionTitle eyebrow="Get started" title="Up and running in minutes" />
85	        <ol className="mx-auto mt-10 max-w-3xl space-y-3">
86	          {content.steps.map((s, i) => (
87	            <Reveal as="li" key={s.title} delay={i * 60} className="card flex gap-4">
88	              <span className="flex h-8 w-8 flex-none items-center justify-center rounded-lg bg-brand-500/20 text-sm font-bold text-brand-200">
89	                {i + 1}
90	              </span>
91	              <div>
92	                <h3 className="text-sm font-semibold text-white">{s.title}</h3>
93	                <p className="mt-1 text-sm leading-relaxed text-slate-400">{s.body}</p>
94	              </div>
95	            </Reveal>
96	          ))}
97	        </ol>
98	      </Section>
99	
100	      {/* Real plans */}
101	      {plans.length > 0 && (
102	        <Section tone="panel" size="lg" id="pricing">
103	          <SectionTitle eyebrow="Plans" title="Pick your size" sub={content.specNote} />
104	          <Reveal className="mt-10">
105	            <PricingGrid plans={plans} />
106	          </Reveal>
107	        </Section>
108	      )}
109	
110	      {/* FAQ */}
111	      <Section tone="base" size="md">
112	        <SectionTitle eyebrow="FAQ" title="Questions, answered" />
113	        <div className="mx-auto mt-10 max-w-3xl space-y-3">
114	          {content.faq.map((f) => (
115	            <details key={f.q} className="card group">
116	              <summary className="cursor-pointer list-none font-medium text-white marker:content-none">
117	                <span className="flex items-center justify-between gap-4">
118	                  {f.q}
119	                  <span className="text-slate-500 transition-transform group-open:rotate-45">+</span>
120	                </span>
121	              </summary>
122	              <p className="mt-3 text-sm leading-relaxed text-slate-400">{f.a}</p>
123	            </details>
124	          ))}
125	        </div>
126	      </Section>
127	
128	      {content.related && content.related.length > 0 && (
129	        <Section tone="base" size="sm">
130	          <div className="mx-auto flex max-w-3xl flex-wrap items-center justify-center gap-2">
131	            <span className="text-xs font-semibold uppercase tracking-wider text-slate-500">Related</span>
132	            {content.related.map((r) => (
133	              <Link
134	                key={r.href}
135	                href={r.href}
136	                className="rounded-full border border-white/10 bg-white/[0.03] px-3 py-1 text-sm text-slate-300 transition-colors hover:border-white/20 hover:text-white"
137	              >
138	                {r.label}
139	              </Link>
140	            ))}
141	          </div>
142	        </Section>
143	      )}
144	
145	      <Section tone="deep" size="lg">
146	        <CtaBand />
147	      </Section>
148	    </>
149	  );
150	}
