export type PlanCard = {
  id: string;
  name: string;
  cpuCores: number;
  ramMB: number;
  diskGB: number;
  bandwidthTB: number;
  priceCents: number;
  storageTier: string;
};

function planFeatures(p: PlanCard): string[] {
  const disk = p.storageTier === "hdd" ? "HDD storage" : "NVMe SSD storage";
  return [
    `${p.cpuCores} vCPU core${p.cpuCores > 1 ? "s" : ""}`,
    `${(p.ramMB / 1024).toFixed(p.ramMB % 1024 ? 1 : 0)} GB RAM`,
    `${p.diskGB} GB ${disk}`,
    `${p.bandwidthTB} TB bandwidth`,
    "Full root access",
    "Free DDoS protection",
  ];
}

export function PricingGrid({ plans, annualPct = 0 }: { plans: PlanCard[]; annualPct?: number }) {
  // Prices are USD-cents in the DB; `money` converts them to the visitor's display
  // currency (geo/manual) for rendering only — checkout still charges the USD amount.
  const money = useDisplayMoney();
  // Billing toggle — Annual is on by default when it's a real discount, so the
  // headline price shows the better-value figure first. Switching to Monthly shows
  // the undiscounted monthly price. Every figure is DB-fed through termPriceCents,
  // the SAME formula checkout charges — displayed === charged.
  const annualAvailable = annualPct > 0;
  const [annual, setAnnual] = useState(true);
