import type { Metadata } from "next";
import { db } from "@/lib/db";
import { LocationLanding, type LocationReason } from "@/components/marketing/locationtemplate/LocationLanding";
import type { LocationPlan } from "@/components/marketing/locationtemplate/data";
import { ReviewBadges } from "@/components/marketing/ReviewBadges";
import { APP_URL, FaqJsonLd, ProductOffersJsonLd } from "@/components/marketing/StructuredData";
import {
  LOCATIONS_BY_SLUG,
  SERVICES,
  buildLanding,
  type Combo,
  type LandingPlan,
} from "@/lib/marketing/locationLandings";

/**
 * Singapore Game Server Hosting — the location-template renderer, second
 * combo migrated off the generic `[slug]` catch-all (after singapore-vps-hosting).
 *
 * All copy (hero, "why", FAQ, metadata) is generated by the SAME `buildLanding`
 * function that powers every other location×service page — nothing here is
 * hand-invented — so this page stays byte-for-byte in sync with the shared
 * copy engine while rendering through the richer `LocationLanding` template
 * instead of the generic `UseCaseLanding` shell. Real per-game pricing (not
 * the VPS price floor) drives both the "from $X/mo" copy and the plan cards.
 */

export const dynamic = "force-dynamic";

const SINGAPORE = LOCATIONS_BY_SLUG.get("singapore")!;
const GAME_SERVICE = SERVICES.find((s) => s.key === "game")!;
const COMBO: Combo = { location: SINGAPORE, service: GAME_SERVICE, slug: "singapore-game-server-hosting" };

function toLandingPlan(p: { id: string; ramMB: number; cpuCores: number; diskGB: number; priceCents: number }): LandingPlan {
  return { id: p.id, name: "", cpuCores: p.cpuCores, ramMB: p.ramMB, diskGB: p.diskGB, bandwidthTB: 1, priceCents: p.priceCents, storageTier: "nvme" };
}

export async function generateMetadata(): Promise<Metadata> {
  const plans = await db.gamePlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } });
  const built = buildLanding(COMBO, plans.map(toLandingPlan));
  return {
    title: built.metaTitle,
    description: built.metaDescription,
    alternates: { canonical: `/${COMBO.slug}` },
    openGraph: { type: "article", title: built.ogTitle, description: built.ogDescription, url: `${APP_URL}/${COMBO.slug}` },
  };
}

export default async function SingaporeGameServerHostingPage() {
  const gamePlans = await db.gamePlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } });
  const built = buildLanding(COMBO, gamePlans.map(toLandingPlan));
  const { content } = built;

  // Feature the two cheapest real, active game plans (usually Minecraft's
  // entry tiers) so the price shown on the card is a real, bookable SKU —
  // never a made-up "from" figure.
  const featured = gamePlans.slice(0, 2);
  const locationPlans: LocationPlan[] = featured.map((p, i) => ({
    id: p.id,
    kind: "Game",
    tier: i === 0 ? "Game server · Starter" : "Game server · Popular",
    price: `$${(p.priceCents / 100).toFixed(2)}`,
    headline: p.name,
    meta: `${p.ramMB >= 1024 ? `${(p.ramMB / 1024).toFixed(p.ramMB % 1024 ? 1 : 0)} GB RAM` : `${p.ramMB} MB RAM`}${p.slots ? ` · ${p.slots} slots` : ""}`,
    features: ["One-click game installs", "Full file + FTP access", "Singapore low-latency network", "Always-on DDoS protection"],
    popular: i === 1,
  }));

  const reasons: LocationReason[] = content.why.slice(0, 4).map((w, i) => ({
    n: String(i + 1).padStart(2, "0"),
    title: w.title,
    body: w.body,
  }));

  return (
    <>
      <ProductOffersJsonLd
        name="Nxeon Singapore Game Servers"
        description={built.metaDescription}
        url={`${APP_URL}/game-servers`}
        offers={locationPlans.map((p) => ({ name: `${p.tier} · ${p.headline} (Singapore)`, price: Number(p.price.replace(/[^0-9.]/g, "")) }))}
      />
      <FaqJsonLd items={content.faq} />
      <LocationLanding
        reviewBadges={<ReviewBadges />}
        plans={locationPlans}
        hero={{
          eyebrowPill: "Singapore game servers · SGP region",
          titleLead: content.title,
          titleHighlight: content.highlight,
          sub: content.sub,
          liveLabel: "Your Singapore game server is",
          liveValue: "60 seconds",
          ctaLabel: "Deploy a game server",
          ctaHref: "/game-servers",
        }}
        reasons={reasons}
        reasonsEyebrow="Why deploy here"
        reasonsTitle={content.whyTitle}
        plansEyebrow="Deploy in Singapore"
        plansTitle="Pick your game. We'll pin it to SGP."
        plansSub="Real per-game pricing, provisioned in the Singapore region on enterprise NVMe."
        closingLead="Put your game server where Asia connects."
        closingHighlight="60 seconds"
        closingPrimary={{ label: "Deploy a game server", href: "/game-servers" }}
        closingSecondary={{ label: "VPS hosting", href: "/vps" }}
      />
    </>
  );
}

