1	import type { Metadata } from "next";
2	import { db } from "@/lib/db";
3	import { LocationLanding, type LocationReason } from "@/components/marketing/locationtemplate/LocationLanding";
4	import type { LocationPlan } from "@/components/marketing/locationtemplate/data";
5	import { ReviewBadges } from "@/components/marketing/ReviewBadges";
6	import { APP_URL, FaqJsonLd, ProductOffersJsonLd } from "@/components/marketing/StructuredData";
7	import {
8	  LOCATIONS_BY_SLUG,
9	  SERVICES,
10	  buildLanding,
11	  type Combo,
12	  type LandingPlan,
13	} from "@/lib/marketing/locationLandings";
14	
15	/**
16	 * Singapore Game Server Hosting — the location-template renderer, second
17	 * combo migrated off the generic `[slug]` catch-all (after singapore-vps-hosting).
18	 *
19	 * All copy (hero, "why", FAQ, metadata) is generated by the SAME `buildLanding`
20	 * function that powers every other location×service page — nothing here is
21	 * hand-invented — so this page stays byte-for-byte in sync with the shared
22	 * copy engine while rendering through the richer `LocationLanding` template
23	 * instead of the generic `UseCaseLanding` shell. Real per-game pricing (not
24	 * the VPS price floor) drives both the "from $X/mo" copy and the plan cards.
25	 */
26	
27	export const dynamic = "force-dynamic";
28	
29	const SINGAPORE = LOCATIONS_BY_SLUG.get("singapore")!;
30	const GAME_SERVICE = SERVICES.find((s) => s.key === "game")!;
31	const COMBO: Combo = { location: SINGAPORE, service: GAME_SERVICE, slug: "singapore-game-server-hosting" };
32	
33	function toLandingPlan(p: { id: string; ramMB: number; cpuCores: number; diskGB: number; priceCents: number }): LandingPlan {
34	  return { id: p.id, name: "", cpuCores: p.cpuCores, ramMB: p.ramMB, diskGB: p.diskGB, bandwidthTB: 1, priceCents: p.priceCents, storageTier: "nvme" };
35	}
36	
37	export async function generateMetadata(): Promise<Metadata> {
38	  const plans = await db.gamePlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } });
39	  const built = buildLanding(COMBO, plans.map(toLandingPlan));
40	  return {
41	    title: built.metaTitle,
42	    description: built.metaDescription,
43	    alternates: { canonical: `/${COMBO.slug}` },
44	    openGraph: { type: "article", title: built.ogTitle, description: built.ogDescription, url: `${APP_URL}/${COMBO.slug}` },
45	  };
46	}
47	
48	export default async function SingaporeGameServerHostingPage() {
49	  const gamePlans = await db.gamePlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } });
50	  const built = buildLanding(COMBO, gamePlans.map(toLandingPlan));
51	  const { content } = built;
52	
53	  // Feature the two cheapest real, active game plans (usually Minecraft's
54	  // entry tiers) so the price shown on the card is a real, bookable SKU —
55	  // never a made-up "from" figure.
56	  const featured = gamePlans.slice(0, 2);
57	  const locationPlans: LocationPlan[] = featured.map((p, i) => ({
58	    id: p.id,
59	    kind: "Game",
60	    tier: i === 0 ? "Game server · Starter" : "Game server · Popular",
61	    price: `$${(p.priceCents / 100).toFixed(2)}`,
62	    headline: p.name,
63	    meta: `${p.ramMB >= 1024 ? `${(p.ramMB / 1024).toFixed(p.ramMB % 1024 ? 1 : 0)} GB RAM` : `${p.ramMB} MB RAM`}${p.slots ? ` · ${p.slots} slots` : ""}`,
64	    features: ["One-click game installs", "Full file + FTP access", "Singapore low-latency network", "Always-on DDoS protection"],
65	    popular: i === 1,
66	  }));
67	
68	  const reasons: LocationReason[] = content.why.slice(0, 4).map((w, i) => ({
69	    n: String(i + 1).padStart(2, "0"),
70	    title: w.title,
71	    body: w.body,
72	  }));
73	
74	  return (
75	    <>
76	      <ProductOffersJsonLd
77	        name="Nxeon Singapore Game Servers"
78	        description={built.metaDescription}
79	        url={`${APP_URL}/game-servers`}
80	        offers={locationPlans.map((p) => ({ name: `${p.tier} · ${p.headline} (Singapore)`, price: Number(p.price.replace(/[^0-9.]/g, "")) }))}
81	      />
82	      <FaqJsonLd items={content.faq} />
83	      <LocationLanding
84	        reviewBadges={<ReviewBadges />}
85	        plans={locationPlans}
86	        hero={{
87	          eyebrowPill: "Singapore game servers · SGP region",
88	          titleLead: content.title,
89	          titleHighlight: content.highlight,
90	          sub: content.sub,
91	          liveLabel: "Your Singapore game server is",
92	          liveValue: "60 seconds",
93	          ctaLabel: "Deploy a game server",
94	          ctaHref: "/game-servers",
95	        }}
96	        reasons={reasons}
97	        reasonsEyebrow="Why deploy here"
98	        reasonsTitle={content.whyTitle}
99	        plansEyebrow="Deploy in Singapore"
100	        plansTitle="Pick your game. We'll pin it to SGP."
101	        plansSub="Real per-game pricing, provisioned in the Singapore region on enterprise NVMe."
102	        closingLead="Put your game server where Asia connects."
103	        closingHighlight="60 seconds"
104	        closingPrimary={{ label: "Deploy a game server", href: "/game-servers" }}
105	        closingSecondary={{ label: "VPS hosting", href: "/vps" }}
106	      />
107	    </>
108	  );
109	}
