content.content:
model Plan {
  id           String        @id @default(cuid())
  slug         String        @unique
  name         String
  cpuCores     Int
  ramMB        Int
  diskGB       Int
  bandwidthTB  Float         @default(1)
  priceCents   Int
  /// LOW introductory MONTHLY price (cents) charged for the FIRST term only; the
  /// plan then RENEWS at the regular `priceCents` (classic hosting promo — e.g.
  /// "$3.99/mo first term, renews at $6.49/mo"). NULL = no intro (the plan bills
  /// `priceCents` from day one). Reused through the existing first-term-discount
  /// plumbing: the order stamps the implied first-term rate on
  /// `Server.termPromoPercent`, and every renewal path (lib/renewal-charge.ts)
  /// reads `priceCents` and knows nothing about this column, so renewal === regular
  /// by construction. Only honoured when strictly below `priceCents`.
  introPriceCents Int?
  /// How many of the first term's months are billed at `introPriceCents` before the
  /// remainder of that term reverts to the regular rate. NULL = the WHOLE first term
  /// is at the intro price (the common "$X first month, then $Y/mo" case is
  /// `introTermMonths = 1`). Ignored when `introPriceCents` is null.
  introTermMonths Int?
  storageTier  String        @default("nvme") // "nvme" | "hdd"
  active       Boolean       @default(true)
  sortOrder    Int           @default(0)
  createdAt    DateTime      @default(now())
  servers      Server[]
  gamePlans    GamePlan[]
